/* Pure situation module: no clock, IO or globals. The simulation below is a line-for-line port of
 * ui/src/game.ts::step (the gameplay authority); test/situation.test.ts enforces parity. */
export const STEP = 1 / 120
export const ACTION_TICKS = 84 // 700 ms
export const TAIL_MS = 400
export const TAIL_TICKS = 48
export const DEFAULT_LATENCY_MS = 1500
export const HORIZON_AHEAD = 480
export const HORIZON_BEHIND = 240
export type Input = { left: boolean; right: boolean; jump: boolean }
export interface Sim { level: Level; x: number; y: number; vy: number; grounded: boolean; jumpHeld: boolean; facing: number; lives: number; score: number; collected: Set<string>; enemies: (Enemy & { direction: number })[]; status: 'running' | 'paused' | 'won' | 'lost'; ticks: number; immunity: number; coinPoints: number }
export type StepEvent = { kind: 'fell'; x: number; y: number } | { kind: 'enemy'; id: string; x: number; y: number } | null
const overlap = (x: number, y: number, w: number, h: number, r: Rect) => x < r.x + r.width && x + w > r.x && y < r.y + r.height && y + h > r.y
function damage(g: Sim) { g.lives--; g.vy = 0; g.jumpHeld = false; if (!g.lives) { g.status = 'lost'; return } g.x = g.level.spawn.x; g.y = g.level.spawn.y; g.grounded = true; g.immunity = 0.8; g.enemies = g.level.enemies.map(e => ({ ...e, direction: 1 })) }
/** One fixed tick, same order as ui/src/game.ts::step; returns the damage cause (pre-respawn position). */
export function step(g: Sim, input: Input): StepEvent {
  if (g.status !== 'running') return null
  g.ticks++; g.immunity = Math.max(0, g.immunity - STEP)
