  if (dx) g.facing = Math.sign(dx)
  if (input.jump && !g.jumpHeld && g.grounded) { g.vy = -l.physics.jumpSpeed; g.grounded = false }
  g.jumpHeld = input.jump
  g.x = Math.max(0, Math.min(l.width - 24, g.x + dx))
  for (const p of l.platforms) if (overlap(g.x, g.y, 24, 32, p)) { if (dx > 0) g.x = p.x - 24; else if (dx < 0) g.x = p.x + p.width }
  const oldY = g.y; g.vy += l.physics.gravity * STEP; g.y += g.vy * STEP; g.grounded = false
  for (const p of l.platforms) if (overlap(g.x, g.y, 24, 32, p)) {
    if (g.vy >= 0 && oldY + 32 <= p.y + 0.001) { g.y = p.y - 32; g.vy = 0; g.grounded = true }
    else if (g.vy < 0 && oldY >= p.y + p.height - 0.001) { g.y = p.y + p.height; g.vy = 0 }
