  for (const c of l.coins) if (!g.collected.has(c.id) && Math.hypot(c.x - Math.max(g.x, Math.min(c.x, g.x + 24)), c.y - Math.max(g.y, Math.min(c.y, g.y + 32))) <= c.radius) { g.collected.add(c.id); g.score += g.coinPoints }
