}
export const inputFor = (choice: Choice): Input => ({ left: choice === 'left' || choice === 'left_jump', right: choice === 'right' || choice === 'right_jump', jump: choice === 'jump' || choice === 'left_jump' || choice === 'right_jump' })
const idle: Input = { left: false, right: false, jump: false }
const r1 = (n: number) => Math.round(n * 10) / 10
const clone = (g: Sim): Sim => ({ ...g, collected: new Set(g.collected), enemies: g.enemies.map(e => ({ ...e })) })

export interface Pit { id: string; x0: number; x1: number; top: number }
/** Gaps between ground platforms (those sharing the lowest top). */
export function pits(level: Level): Pit[] {
  const top = Math.max(...level.platforms.map(p => p.y))
  const ground = level.platforms.filter(p => p.y === top).sort((a, b) => a.x - b.x)
  const out: Pit[] = []
  for (let i = 1; i < ground.length; i++) { const x0 = ground[i - 1]!.x + ground[i - 1]!.width, x1 = ground[i]!.x; if (x1 > x0) out.push({ id: `pit-${x0}-${x1}`, x0, x1, top }) }
  return out
}
function support(level: Level, x: number, y: number, exact: boolean): Rect | null {
  const under = level.platforms.filter(p => x < p.x + p.width && x + 24 > p.x && (exact ? Math.abs(p.y - (y + 32)) < 0.01 : p.y >= y + 32 - 0.01)).sort((a, b) => a.y - b.y)
  return under[0] ?? null
}
const inPit = (ps: Pit[], g: Sim) => g.y + 32 > ps[0]!.top + 0.001 ? ps.find(p => g.x + 24 > p.x0 && g.x < p.x1) ?? null : null

export interface SituationInput {
  level: Level; report: ReportedState; received_at_unix_ms: number
  before: { report: ReportedState; received_at_unix_ms: number } | null
  latency_ms: number | null
}
export function estimateVy(input: SituationInput): { vy: number; vy_source: 'grounded' | 'previous_report' | 'assumed_zero' } {
  const { report, before, level } = input
  if (report.grounded) return { vy: 0, vy_source: 'grounded' }
  const dt = before ? (input.received_at_unix_ms - before.received_at_unix_ms) / 1000 : 0
  if (before && dt > 0 && dt <= 0.3 && (before.report.session_id ?? null) === (report.session_id ?? null))
    return { vy: r1((report.y - before.report.y) / dt + level.physics.gravity * dt / 2), vy_source: 'previous_report' }
