}
type Timed = { effect: SituationEffect; tick: number }
interface Run { outcome: MovePrediction['outcome']; effects: Timed[]; end: Sim; terminal: Timed | null }
/** Run `ticks` with `input`; stops at the first contact or pit fall. `threats` gates clears_enemy. */
function run(start: Sim, input: Input, ticks: number, pitList: Pit[], threats: Set<string>, offset: number): Run {
  const g = clone(start), effects: Timed[] = []
