  const cleared = new Set<string>()
  for (let i = 1; i <= ticks; i++) {
    const coins = new Set(g.collected)
    const event = step(g, input)
    if (event) {
      const pit = event.kind === 'fell' ? pitList.find(p => event.x + 24 > p.x0 && event.x < p.x1) ?? null : null
      const t = { effect: event.kind === 'enemy' ? { kind: 'hits_enemy' as const, target_id: event.id } : { kind: 'falls_in_pit' as const, target_id: pit?.id ?? null }, tick: offset + i }
      const kept = effects.filter(e => !(e.effect.kind === 'clears_enemy' && e.effect.target_id === t.effect.target_id))
      g.x = event.x; g.y = event.y
      return { outcome: event.kind === 'enemy' ? 'collision' : 'fall', effects: [...kept, t], end: g, terminal: t }
    }
    for (const id of g.collected) if (!coins.has(id)) effects.push({ effect: { kind: 'collects_coin', target_id: id }, tick: offset + i })
