      const side = Math.sign(mc(g) - (e.x + e.width / 2))
      if (under || (side !== 0 && order.get(e.id) !== 0 && side !== order.get(e.id))) { cleared.add(e.id); effects.push({ effect: { kind: 'clears_enemy', target_id: e.id }, tick: offset + i }) }
