}
const names: Record<SituationEffect['kind'], string> = { hits_enemy: 'colide com o guardião', falls_in_pit: 'cai no buraco', collects_coin: 'pega a moeda', lands_on_platform: 'sobe na plataforma', clears_enemy: 'livra o guardião', safe: 'seguro' }
