    if (!effects.length) effects.push({ kind: 'safe', target_id: null })
    const dx = r1(r.end.x - x)
    if (choice === 'idle' || choice === 'left' || choice === 'right') {
      const hit = r.terminal ?? (risk ? { effect: risk, tick: riskTick! } : null)
      if (hit?.effect.target_id && (!contact.has(hit.effect.target_id) || contact.get(hit.effect.target_id)! > hit.tick)) contact.set(hit.effect.target_id, hit.tick)
    }
    moves[choice] = { outcome: r.outcome, effects: effects.slice(0, 6), risk_after: risk, end: { x: r1(r.end.x), y: r1(r.end.y), grounded: r.end.grounded }, dx_px: dx, label: label(effects.slice(0, 6), dx) }
