  return {
    version: 1, level_id: level.id, session_id: report.session_id ?? null, report_seq: report.report_seq ?? null, received_at_unix_ms: input.received_at_unix_ms,
    mario: { x: report.x, y: report.y, grounded: report.grounded, facing: report.facing, vy, vy_source },
    timing: { latency_ms, latency_source: input.latency_ms === null ? 'default' : 'previous_decision', action_ms: 700, tail_ms: TAIL_MS },
    jump: { apex_px: Math.round(apex), air_ms: Math.round(2 * ph.jumpSpeed / ph.gravity * 1000), reach_px: Math.round(ph.moveSpeed * 2 * ph.jumpSpeed / ph.gravity), walk_px_in_action: Math.round(ph.moveSpeed * 0.7) },
    threats, opportunities, priority, moves,
  }
}
