/** Predicted effect of the chosen move, copied from the same situation sent to the Judge. */
export function predictedFor(situation: MarioSituation, choice: Choice): PredictedEffect {
  const m = situation.moves[choice]
  const primary = m.effects.find(e => e.kind !== 'safe') ?? null
  return { outcome: m.outcome, effects: structuredClone(m.effects), risk_after: m.risk_after === null ? null : { ...m.risk_after }, label: m.label,
    target_id: primary?.target_id ?? null, target_kind: primary ? kinds[primary.kind] : null, report_seq: situation.report_seq }
}
