/// How the worker resolved (or failed to resolve) Chromium: the config values
/// behind it and every path it probed, in order.
#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct ChromiumDetection {
    /// The configured `executable`; empty means auto-detection.
    pub executable: String,
    /// The configured `browser.scrapling.chromium_executable`; empty means the
    /// scrapling paths fall back to this same detection.
    pub scrapling_executable: String,
    /// The path detection settled on: the first candidate that is a regular,
    /// executable file.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub resolved: Option<String>,
    /// `$PLAYWRIGHT_BROWSERS_PATH` as this process saw it, when set.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub playwright_browsers_path: Option<String>,
    /// Chrome versions the scrapling compat path certifies. The interactive
    /// `browser::*` functions launch any build; compat mode rejects one that
    /// is not in this list.
    pub certified_versions: Vec<String>,
    /// Every path probed, in the order they were tried. Probing stops at the
    /// first accepted path.
    pub candidates: Vec<ChromiumCandidate>,
}

impl ChromiumDetection {
    /// The `issues[]` line for a detection that resolved nothing: the
    /// configured path and why it is unusable, or every path probed with the
    /// reason a launch would refuse it.
    pub fn failure_summary(&self) -> String {
        if !self.executable.is_empty() {
            let reason = self
                .candidates
                .first()
                .map(|candidate| candidate.detail.as_str())
                .unwrap_or("unusable");
            return format!("configured executable '{}' is {reason}", self.executable);
        }
        if self.candidates.is_empty() {
            return "no Chromium/Chrome install found: no candidate path was testable".to_string();
        }
        let probed: Vec<String> = self
            .candidates
            .iter()
            .map(|candidate| format!("{} ({})", candidate.path, candidate.detail))
            .collect();
        format!("no Chromium/Chrome install found: {}", probed.join("; "))
    }
}

/// Candidate system installs, checked before the Playwright caches when the
/// configured `executable` is empty, in order.
#[cfg(target_os = "macos")]
const CANDIDATES: &[&str] = &[
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
];

#[cfg(target_os = "linux")]
const CANDIDATES: &[&str] = &[
    "/usr/bin/google-chrome",
    "/usr/bin/google-chrome-stable",
    "/usr/bin/chromium",
    "/usr/bin/chromium-browser",
    "/usr/bin/microsoft-edge",
];

#[cfg(target_os = "windows")]
const CANDIDATES: &[&str] = &[
    "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
    "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
    "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
];

/// Where the binary sits inside a Playwright `chromium-<build>` directory.
#[cfg(target_os = "macos")]
const PLAYWRIGHT_LEAVES: &[&str] = &["chrome-mac/Chromium.app/Contents/MacOS/Chromium"];

#[cfg(target_os = "windows")]
const PLAYWRIGHT_LEAVES: &[&str] = &["chrome-win64/chrome.exe", "chrome-win/chrome.exe"];

#[cfg(not(any(target_os = "macos", target_os = "windows")))]
const PLAYWRIGHT_LEAVES: &[&str] = &["chrome-linux64/chrome", "chrome-linux/chrome"];

/// How far below a Playwright root to look for `chromium-*` builds:
/// `ms-playwright-go` nests one driver-version directory in between.
const PLAYWRIGHT_SCAN_DEPTH: u32 = 3;

/// The environment the detection reads, injected so a test can pin it instead
/// of mutating the process environment.
#[derive(Debug, Clone, Default)]
struct DetectionEnv {
    playwright_browsers_path: Option<OsString>,
    home: Option<PathBuf>,
}

impl DetectionEnv {
    fn from_process() -> Self {
        Self {
            playwright_browsers_path: std::env::var_os("PLAYWRIGHT_BROWSERS_PATH"),
            home: home_dir(),
        }
    }
}

#[cfg(target_os = "windows")]
fn home_dir() -> Option<PathBuf> {
    std::env::var_os("USERPROFILE").map(PathBuf::from)
}

#[cfg(not(target_os = "windows"))]
fn home_dir() -> Option<PathBuf> {
    std::env::var_os("HOME").map(PathBuf::from)
}

/// Resolve the Chromium binary the worker would launch, reporting every path
/// probed on the way. Blocking on filesystem metadata only; never launches the
/// candidate.
pub fn diagnose_chromium(cfg: &WorkerConfig) -> ChromiumDetection {
    diagnose_chromium_with(cfg, &DetectionEnv::from_process(), CANDIDATES)
}

/// Resolve the Chromium binary the worker would launch: the configured
/// `executable` when set, otherwise the first usable system install, otherwise
/// the newest Playwright build in the caches.
pub fn detect_chromium(cfg: &WorkerConfig) -> Option<PathBuf> {
    diagnose_chromium(cfg).resolved.map(PathBuf::from)
}

fn diagnose_chromium_with(
    cfg: &WorkerConfig,
    env: &DetectionEnv,
    system: &[&str],
) -> ChromiumDetection {
    let mut candidates = Vec::new();

    if !cfg.executable.is_empty() {
        // A configured path is the operator's answer: report it, never
        // second-guess it with a fallback.
        consider(
            &mut candidates,
            PathBuf::from(&cfg.executable),
            "config executable".to_string(),
        );
    } else {
        let mut accepted = false;
        for install in system {
            accepted = consider(
                &mut candidates,
                PathBuf::from(install),
                "system install".to_string(),
            );
            if accepted {
                break;
            }
        }
        if !accepted {
            for (root, label) in playwright_roots(env) {
                let mut builds = Vec::new();
                collect_playwright_chromium(&root, PLAYWRIGHT_SCAN_DEPTH, &mut builds);
                builds.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
                if builds.is_empty() {
                    let mut candidate = probe_candidate(root, label.to_string());
                    candidate.detail = if candidate.status == ChromiumStatus::Missing {
                        "Playwright cache not found here".to_string()
                    } else {
                        "no chromium-* build under this Playwright root".to_string()
                    };
                    candidates.push(candidate);
                    continue;
                }
                for (_, binary) in builds {
                    accepted = consider(&mut candidates, binary, label.to_string());
                    if accepted {
                        break;
                    }
                }
                if accepted {
                    break;
                }
            }
        }
    }

    let resolved = candidates
        .iter()
        .rev()
        .find(|candidate| candidate.status == ChromiumStatus::Accepted)
        .map(|candidate| candidate.path.clone());

    ChromiumDetection {
        executable: cfg.executable.clone(),
        scrapling_executable: cfg.scrapling.chromium_executable.clone(),
        resolved,
        playwright_browsers_path: env
            .playwright_browsers_path
            .as_ref()
            .map(|value| value.to_string_lossy().into_owned()),
        certified_versions: CERTIFIED_CHROME_VERSIONS
            .iter()
            .map(|version| version.to_string())
            .collect(),
        candidates,
    }
}

