#!/usr/bin/env python3
"""A small, dependency-free arithmetic expression calculator."""

import argparse
import sys


class ParseError(ValueError):
    """Raised when an expression is not valid calculator syntax."""


class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def parse(self):
        value = self.expression()
        self.skip_whitespace()
        if self.pos != len(self.text):
            raise ParseError(f"unexpected character {self.text[self.pos]!r}")
        return value

    def skip_whitespace(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def expression(self):
        value = self.term()
        while True:
            self.skip_whitespace()
            if self.consume("+"):
                value += self.term()
            elif self.consume("-"):
                value -= self.term()
            else:
                return value

    def term(self):
        value = self.factor()
        while True:
            self.skip_whitespace()
            if self.consume("*"):
                value *= self.factor()
            elif self.consume("/"):
                divisor = self.factor()
                if divisor == 0:
                    raise ParseError("division by zero")
                value /= divisor
            else:
                return value

    def factor(self):
        self.skip_whitespace()
        if self.consume("+"):
            return self.factor()
        if self.consume("-"):
            return -self.factor()
        if self.consume("("):
            value = self.expression()
            self.skip_whitespace()
            if not self.consume(")"):
                raise ParseError("missing closing parenthesis")
            return value

        start = self.pos
        digits = False
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
            digits = True
        if self.pos < len(self.text) and self.text[self.pos] == ".":
            self.pos += 1
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self.pos += 1
                digits = True
        if not digits:
            if self.pos >= len(self.text):
                raise ParseError("expected a number")
            raise ParseError(f"unexpected character {self.text[self.pos]!r}")
        return float(self.text[start:self.pos])

    def consume(self, character):
        if self.pos < len(self.text) and self.text[self.pos] == character:
            self.pos += 1
            return True
        return False


def format_result(value):
    if value.is_integer():
        return str(int(value))
    return str(value)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Safely evaluate an arithmetic expression using +, -, *, /, and parentheses."
    )
    parser.add_argument("expression", help="arithmetic expression to evaluate")
    args = parser.parse_args(argv)

    if not args.expression.strip():
        parser.error("expression must not be empty")
    try:
        result = Parser(args.expression).parse()
    except ParseError as error:
        parser.error(str(error))
    print(format_result(result))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (BrokenPipeError, KeyboardInterrupt):
        sys.exit(1)

