#!/usr/bin/env python3
"""Small, dependency-free command-line expression calculator."""

import math
import re
import sys

MAX_EXPRESSION_LENGTH = 100000
MAX_TOKENS = 50000
NUMBER = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")


class CalculatorError(Exception):
    """An expected user-input or arithmetic error."""


def tokenize(text):
    tokens = []
    position = 0
    while position < len(text):
        if text[position].isspace():
            position += 1
            continue
        match = NUMBER.match(text, position)
        if match:
            tokens.append(("number", match.group()))
            position = match.end()
        elif text[position] in "+-*/()":
            tokens.append((text[position], text[position]))
            position += 1
        else:
            raise CalculatorError("invalid character")
        if len(tokens) > MAX_TOKENS:
            raise CalculatorError("expression is too long")
    return tokens


def evaluate(text):
    if not text.strip():
        raise CalculatorError("expression is empty")
    if len(text) > MAX_EXPRESSION_LENGTH:
        raise CalculatorError("expression is too long")

    output = []
    operators = []
    expect_operand = True
    precedence = {"u+": 3, "u-": 3, "*": 2, "/": 2, "+": 1, "-": 1}
    right_associative = {"u+", "u-"}

    for kind, value in tokenize(text):
        if kind == "number":
            if not expect_operand:
                raise CalculatorError("missing operator")
            output.append((kind, value))
            expect_operand = False
        elif kind == "(":
            if not expect_operand:
                raise CalculatorError("missing operator")
            operators.append(kind)
        elif kind == ")":
            if expect_operand:
                raise CalculatorError("unexpected closing parenthesis")
            while operators and operators[-1] != "(":
                output.append(("operator", operators.pop()))
            if not operators:
                raise CalculatorError("unmatched closing parenthesis")
            operators.pop()
            expect_operand = False
        else:
            operator = kind
            if expect_operand:
                if operator not in "+-":
                    raise CalculatorError("operator needs a number")
                operator = "u" + operator
            while (operators and operators[-1] != "(" and
                   (precedence[operators[-1]] > precedence[operator] or
                    (precedence[operators[-1]] == precedence[operator] and
                     operator not in right_associative))):
                output.append(("operator", operators.pop()))
            operators.append(operator)
            expect_operand = True

    if expect_operand:
        raise CalculatorError("expression ends with an operator")
    while operators:
        if operators[-1] == "(":
            raise CalculatorError("unmatched opening parenthesis")
        output.append(("operator", operators.pop()))

    values = []
    for kind, value in output:
        if kind == "number":
            try:
                number = float(value)
            except ValueError:
                raise CalculatorError("invalid number")
            if not math.isfinite(number):
                raise CalculatorError("number is not finite")
            values.append(number)
            continue
        if value in ("u+", "u-"):
            if not values:
                raise CalculatorError("invalid expression")
            operand = values.pop()
            values.append(operand if value == "u+" else -operand)
            continue
        if len(values) < 2:
            raise CalculatorError("invalid expression")
        right = values.pop()
        left = values.pop()
        if value == "+":
            result = left + right
        elif value == "-":
            result = left - right
        elif value == "*":
            result = left * right
        else:
            if right == 0:
                raise CalculatorError("division by zero")
            result = left / right
        if not math.isfinite(result):
            raise CalculatorError("result is not finite")
        values.append(result)
    if len(values) != 1:
        raise CalculatorError("invalid expression")
    return values[0]


def main(argv):
    if len(argv) != 2:
        print("usage: calc.py EXPR", file=sys.stderr)
        return 2
    try:
        result = evaluate(argv[1])
    except CalculatorError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    if result == int(result):
        print(int(result))
    else:
        print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
